<?php defined( 'ABSPATH' ) || exit; $categories = get_the_terms( get_the_ID(), 'project_cat' ); $locations = get_the_terms( get_the_ID(), 'project_location' ); ?>
<a class="project-card" href="<?php echo esc_url( get_permalink() ); ?>"><div class="project-card__image"><?php if ( has_post_thumbnail() ) { the_post_thumbnail( 'es-card', array( 'loading' => 'lazy' ) ); } else { echo '<img loading="lazy" src="' . esc_url( es_asset( 'images/light-tunnel.jpg' ) ) . '" alt="">'; } ?><span class="project-card__arrow" aria-hidden="true">↗</span></div><div class="project-card__info"><span class="project-card__meta"><?php echo esc_html( $categories && ! is_wp_error( $categories ) ? $categories[0]->name : 'نورپردازی شهری' ); ?><?php if ( $locations && ! is_wp_error( $locations ) ) : ?> · <?php echo esc_html( $locations[0]->name ); endif; ?></span><h3><?php echo esc_html( get_the_title() ); ?></h3><p><?php echo esc_html( es_excerpt( 15 ) ); ?></p></div></a>
